-- Fase 6: la empresa indica si aplica la exoneración del art. 114-1 E.T.
ALTER TABLE "company" ADD COLUMN "parafiscal_exempt" BOOLEAN NOT NULL DEFAULT false;

-- La restricción única (company_id, key, valid_from) no protege los valores
-- nacionales (company_id NULL): en PostgreSQL los NULL no chocan entre sí.
CREATE UNIQUE INDEX "labor_parameter_national_key" ON "labor_parameter" ("key", "valid_from") WHERE "company_id" IS NULL;

-- Una versión no puede terminar antes de empezar.
ALTER TABLE "labor_parameter" ADD CONSTRAINT "labor_parameter_valid_range" CHECK ("valid_to" IS NULL OR "valid_to" >= "valid_from");

-- Parámetros laborales nacionales (generado con scripts/labor-parameters-sql.ts
-- desde prisma/labor-parameters.ts). Quedan sin validar (verified_at NULL)
-- hasta que un contador los revise en Plataforma → Parámetros.
ON CONFLICT DO NOTHING;
